#!/bin/bash
# Code generated by AI (Claude Opus 5.5)

# Renders each chart/tests/<case> with example/chart (depending on chart/ library)
# and diffs the result against chart/tests/<case>/manifest.yaml, TESTDATA=1 rewrites them.

set -euo pipefail

dir="$(realpath "$(dirname "$0")/../..")"

tmpdir="$(mktemp -d)"
trap 'rm -rf "$tmpdir"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# link workload chart
ln -s "$dir/chart" "$tmpdir/chart"

max_jobs="$(nproc)"
pids=()
for casedir in "$dir"/chart/tests/*; do
  # wait -n status is ignored, the final wait on each pid still returns it
  while [ "$(jobs -rp | wc -l)" -ge "$max_jobs" ]; do
    wait -n || true
  done

  (
    name="$(basename "$casedir")"

    # copy example chart and testcase chart (in case it exists) together in one temp directory
    cp -r "$dir/example" "$tmpdir/$name"
    chart="$tmpdir/$name/chart"
    [ ! -d "$casedir/chart" ] || cp -r "$casedir/chart/." "$chart"

    helm dependency update --skip-refresh "$chart"
    if ! helm lint "$chart" --kube-version "$KUBE_VERSION" --values "$casedir/values.yaml"; then
      echo "lint failed: $name" >&2
      exit 1
    fi

    manifest="$tmpdir/$name.yaml"
    if ! helm template workload "$chart" --namespace default --kube-version "$KUBE_VERSION" --values "$casedir/values.yaml" > "$manifest"; then
      echo "template failed: $name" >&2
      exit 1
    fi

    if [ -n "${TESTDATA:-}" ]; then
      cp "$manifest" "$casedir/manifest.yaml"
    else
      diff -u "$casedir/manifest.yaml" "$manifest"
    fi
  )&
  pids+=("$!")
done

status=0
for pid in "${pids[@]}"; do
  wait "$pid" || status=1
done
exit "$status"
